+++ b/training/level-1/L1-040-identifier/validateIdentifier.mjs
@@ -0,0 +1,79 @@
+export function validateIdentifier(input, policy = {}) {
+  const defaultPolicy = {
+    minLength: 1,
+    maxLength: 64,
+    pattern: '^[A-Za-z_][A-Za-z0-9_.-]*$',
+    reserved: [],
+    caseSensitiveReserved: true
+  };
+
+  const mergedPolicy = { ...defaultPolicy, ...policy };
+
+  // Validate policy keys
+  const allowedKeys = ['minLength', 'maxLength', 'pattern', 'reserved', 'caseSensitiveReserved'];
+  for (const key of Object.keys(mergedPolicy)) {
+    if (!allowedKeys.includes(key)) {
+      throw new RangeError(`Unknown policy key: ${key}`);
+    }
+  }
+
+  // Validate policy values
+  if (typeof mergedPolicy.minLength !== 'number' || !Number.isInteger(mergedPolicy.minLength) || mergedPolicy.minLength < 1) {
+    throw new TypeError('minLength must be an integer >= 1');
+  }
+  if (typeof mergedPolicy.maxLength !== 'number' || !Number.isInteger(mergedPolicy.maxLength) || mergedPolicy.maxLength < mergedPolicy.minLength) {
+    throw new RangeError('maxLength must be an integer >= minLength');
+  }
+  if (typeof mergedPolicy.pattern !== 'string') {
+    throw new TypeError('pattern must be a string');
+  }
+  try {
+    new RegExp(mergedPolicy.pattern);
+  } catch (e) {
+    throw new RangeError('Invalid regex pattern');
+  }
+  if (!Array.isArray(mergedPolicy.reserved)) {
+    throw new TypeError('reserved must be an array');
+  }
+  for (const item of mergedPolicy.reserved) {
+    if (typeof item !== 'string') {
+      throw new TypeError('reserved items must be strings');
+    }
+  }
+  if (typeof mergedPolicy.caseSensitiveReserved !== 'boolean') {
+    throw new TypeError('caseSensitiveReserved must be a boolean');
+  }
+
+  // Validate input type
+  if (typeof input !== 'string') {
+    throw new TypeError('input must be a string');
+  }
+
+  const issues = [];
+
+  if (input.length === 0) {
+    issues.push('EMPTY');
+  } else if (input.length < mergedPolicy.minLength) {
+    issues.push('TOO_SHORT');
+  } else if (input.length > mergedPolicy.maxLength) {
+    issues.push('TOO_LONG');
+  }
+
+  const regex = new RegExp(mergedPolicy.pattern, mergedPolicy.caseSensitiveReserved ? '' : 'i');
+  if (!regex.test(input)) {
+    issues.push('PATTERN');
+  }
+
+  const reservedCheck = mergedPolicy.caseSensitiveReserved
+    ? mergedPolicy.reserved
+    : mergedPolicy.reserved.map(r => r.toLowerCase());
+
+  if (reservedCheck.includes(input)) {
+    issues.push('RESERVED');
+  }
+
+  return Object.freeze({
+    valid: issues.length === 0,
+    issues: Object.freeze(issues)
+  });
+}

